#include <moe_topk/protocol_i_permute_share.h>
#include <algorithm>
#include <iostream>
#include <random>
#include <stdexcept>
#include <sys/socket.h>
#include <thread>
#include <unistd.h>
namespace { using namespace moe_topk; void req(bool x,const char*m){if(!x)throw std::runtime_error(m);} ProtocolIBlock192 add(ProtocolIBlock192 a,const ProtocolIBlock192&b){return{a.word0+b.word0,a.word1+b.word1,a.word2+b.word2};}
ProtocolIPermutation pi(std::uint32_t n,int mode){auto p=protocol_i_identity_permutation(n);if(mode==1)std::reverse(p.begin(),p.end());else if(mode==2)for(std::uint32_t i=0;i<n;i+=2)std::swap(p[i],p[i+1]);else if(mode==3)for(std::uint32_t i=0;i<n;++i)p[i]=(i+1)%n;else p=protocol_i_test_permutation(n,0x2100+n);return p;}std::vector<ProtocolIBlock192>x(std::uint32_t n,int mode){std::vector<ProtocolIBlock192>r(n);std::mt19937_64 g(42+n+mode);for(std::uint32_t i=0;i<n;++i)r[i]=mode==0?ProtocolIBlock192{}:mode==1?ProtocolIBlock192{UINT64_MAX,0,i}:ProtocolIBlock192{g(),g(),g()};return r;}
void one(std::uint32_t n,std::uint32_t t,int pm,int xm,std::uint8_t direction,std::uint64_t id){int off[2]{},on[2]{};req(::socketpair(AF_UNIX,SOCK_STREAM,0,off)==0&&::socketpair(AF_UNIX,SOCK_STREAM,0,on)==0,"socket");auto p=pi(n,pm);auto in=x(n,xm);ProtocolIPermuteShareConfig c{0x210000+n,0x220000+t,id,id+100,n,t,direction,15000};ProtocolIPermuteSharePoResult pr;ProtocolIPermuteShareDoResult dr;std::exception_ptr a,b;std::thread po([&]{try{pr=protocol_i_permute_share_po(c,off[0],on[0],p);}catch(...){a=std::current_exception();}}),d([&]{try{dr=protocol_i_permute_share_do(c,off[1],on[1],in);}catch(...){b=std::current_exception();}});po.join();d.join();::close(off[0]);::close(off[1]);::close(on[0]);::close(on[1]);if(a)std::rethrow_exception(a);if(b)std::rethrow_exception(b);auto want=protocol_i_apply_permutation(p,in);for(std::size_t i=0;i<want.size();++i)req(add(pr.share[i],dr.share[i])==want[i],"PS differential");auto l=protocol_i_benes_layout(n,t);req(pr.counters.offline_translation_instances==protocol_i_benes_translation_count(l),"translation count");req(pr.counters.ps_online_rounds==1&&dr.counters.ps_online_rounds==1,"online rounds");req(pr.counters.online_received_bytes==dr.counters.online_sent_bytes,"online bytes");}
void basics(){for(auto n:{2U,4U,8U,16U,64U,256U}){auto p=protocol_i_test_permutation(n,n);auto q=protocol_i_inverse_permutation(p);std::vector<std::uint32_t>x(n);for(std::uint32_t i=0;i<n;++i)x[i]=i;req(protocol_i_apply_permutation(q,protocol_i_apply_permutation(p,x))==x,"inverse");}bool bad=false;try{(void)protocol_i_benes_layout(8,4);}catch(...){bad=true;}req(bad,"unsupported shape");bad=false;try{protocol_i_validate_permutation({0,0});}catch(...){bad=true;}req(bad,"bad pi");}
} int main(){try{basics();std::uint64_t id=1;for(const auto&s:std::vector<std::pair<std::uint32_t,std::uint32_t>>{{2,2},{4,2},{4,4},{8,2},{8,8},{16,2},{16,4},{16,16},{64,4},{256,16}})for(int pm=0;pm<5;++pm)one(s.first,s.second,pm,pm%3,static_cast<std::uint8_t>(pm&1),id++);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
